package cn.workbench;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.*;
import java.sql.Statement;
import java.util.*;
import java.time.*;
import java.math.*;
import static cn.workbench.Records.map;

/** Candidate policy and frozen simulations; no publication endpoint exists. */
@RestController @RequestMapping("/api/v1")
public class CalendarSimulationController {
 final JdbcTemplate db;final Policy p;final Records records;final Writes writes;final Jsons json;
 static final Set<String> VERSION_TABLES=Set.of("company_calendar_version","kpi_simulation_template");
 public CalendarSimulationController(JdbcTemplate db,Policy p,Records records,Writes writes,Jsons json){this.db=db;this.p=p;this.records=records;this.writes=writes;this.json=json;}
 void access(Policy.Actor a,int company,boolean business){if(a.administrator()){p.infrastructureCompany(a,company);if(business)throw ApiException.denied();}else{p.company(a,company);if(!a.leader()&&!a.departmentHead())throw ApiException.denied();}}
 Map<String,Object> version(Map<String,Object> row,String field){var out=map("id",row.get("id"),"companyId",row.get("company_id"),"version",row.get("version"),"name",row.get("name"),"reason",row.get("reason"),"createdAt",Records.instant(row.get("created_at")).toString());var body=json.map(String.valueOf(row.get("payload")));if(field==null)out.putAll(body);else out.put(field,body);return out;}
 @GetMapping("/kpi/calendar-policy") Object policy(HttpServletRequest q,@RequestParam int companyId){var a=p.actor(q);access(a,companyId,false);List<Map<String,Object>> calendars=new ArrayList<>();for(var row:db.queryForList("SELECT * FROM company_calendar_version WHERE company_id=? ORDER BY version DESC LIMIT 200",companyId)){var v=version(row,"calendar");if(a.departmentHead()){var cal=new LinkedHashMap<>((Map<String,Object>)v.get("calendar"));cal.put("leaves",CalendarPolicy.list(cal.getOrDefault("leaves",List.of())).stream().filter(l->l instanceof Map<?,?> m&&Jsons.integer(m.get("deptId"))==a.dept()).toList());v.put("calendar",cal);}calendars.add(v);}var templates=db.queryForList("SELECT * FROM kpi_simulation_template WHERE company_id=? ORDER BY version DESC LIMIT 200",companyId).stream().map(row->version(row,null)).toList();List<Map<String,Object>> simulations=a.administrator()?List.of():db.queryForList("SELECT id,period,reason,created_at FROM calendar_simulation WHERE company_id=?"+(a.departmentHead()?" AND dept_id=?":"")+" ORDER BY id DESC LIMIT 200",a.departmentHead()?new Object[]{companyId,a.dept()}:new Object[]{companyId}).stream().map(s->map("id",s.get("id"),"period",s.get("period"),"reason",s.get("reason"),"createdAt",Records.instant(s.get("created_at")).toString())).toList();return Api.ok(map("companyId",companyId,"calendars",calendars,"templates",templates,"simulations",simulations,"allowedActions",a.administrator()?List.of("createCalendar","createTemplate"):List.of("simulate")));}
 void lockCompany(int company){if(db.queryForList("SELECT id FROM company WHERE id=? AND enabled=TRUE FOR UPDATE",company).isEmpty())throw ApiException.denied();}
 int nextVersion(String table,int company){if(!VERSION_TABLES.contains(table))throw new IllegalArgumentException();return Objects.requireNonNull(db.queryForObject("SELECT COALESCE(MAX(version),0) FROM "+table+" WHERE company_id=?",Integer.class,company))+1;}
 long insert(String sql,Object... args){var key=new GeneratedKeyHolder();db.update(connection->{var statement=connection.prepareStatement(sql,new String[]{"id"});for(int i=0;i<args.length;i++)statement.setObject(i+1,args[i]);return statement;},key);return Objects.requireNonNull(key.getKey()).longValue();}
 @PostMapping("/kpi/calendar-versions") Object createCalendar(HttpServletRequest q,@RequestBody Map<String,Object> body){var a=p.actor(q);p.admin(a);p.freshTotp(q);int company=TaskService.integer(body,"companyId");access(a,company,false);return writes.run(q,body,()->{if(!(body.get("calendar") instanceof Map<?,?> raw))throw TaskService.invalid("缺少日历配置");Map<String,Object> calendar=new TreeMap<>();raw.forEach((k,v)->calendar.put(String.valueOf(k),v));var parsed=CalendarPolicy.validate(calendar);for(var leave:parsed.leaves()){var department=records.get(leave.dept());if(!"DEPARTMENT".equals(department.get("kind"))||Jsons.integer(department.get("companyId"))!=company)throw ApiException.denied();if(leave.user()!=null&&records.db.scopes(leave.user()).stream().noneMatch(s->Objects.equals(company,s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))&&Objects.equals(leave.dept(),s.get("deptId")==null?null:Jsons.integer(s.get("deptId")))))throw ApiException.denied();}lockCompany(company);int version=nextVersion("company_calendar_version",company);if(TaskService.integer(body,"expectedVersion")!=version-1)throw ApiException.conflict();long id=insert("INSERT INTO company_calendar_version(company_id,version,name,reason,payload,created_by) VALUES(?,?,?,?,?,?)",company,version,TaskService.text(body,"name",100),TaskService.text(body,"reason",1000),json.write(calendar),a.uid());writes.audit(a,"CALENDAR_CANDIDATE_CREATE",id);return version(db.queryForMap("SELECT * FROM company_calendar_version WHERE id=?",id),"calendar");});}
 @PostMapping("/kpi/simulation-templates") Object createTemplate(HttpServletRequest q,@RequestBody Map<String,Object> body){var a=p.actor(q);p.admin(a);p.freshTotp(q);int company=TaskService.integer(body,"companyId");access(a,company,false);if(!Boolean.TRUE.equals(body.get("simulation")))throw TaskService.invalid("候选模板仅支持simulation=true");return writes.run(q,body,()->{var weights=CalendarPolicy.weights(body.get("weights"));var complexity=CalendarPolicy.complexity(body.get("complexityWeights"));lockCompany(company);int version=nextVersion("kpi_simulation_template",company);long id=insert("INSERT INTO kpi_simulation_template(company_id,version,name,reason,payload,created_by) VALUES(?,?,?,?,?,?)",company,version,TaskService.text(body,"name",100),TaskService.text(body,"reason",1000),json.write(map("weights",weights,"complexityWeights",complexity,"simulation",true)),a.uid());writes.audit(a,"KPI_CANDIDATE_CREATE",id);return version(db.queryForMap("SELECT * FROM kpi_simulation_template WHERE id=?",id),null);});}
 Map<String,Object> classificationData(long taskId){var rows=db.queryForList("SELECT * FROM task_classification_version WHERE task_id=? ORDER BY version DESC LIMIT 1",taskId);if(rows.isEmpty())return map("complexity","NORMAL","category","NORMAL","version",0);var row=rows.getFirst();return map("complexity",row.get("complexity"),"category",row.get("category"),"version",row.get("version"),"reason",row.get("reason"),"createdAt",Records.instant(row.get("created_at")).toString());}
 @GetMapping("/tasks/{id}/classification") Object classification(HttpServletRequest q,@PathVariable long id){var a=p.actor(q);var task=p.task(a,id);var data=classificationData(id);data.put("allowedActions",a.leader()&&Domain.companyAllowed(a.role(),a.company(),Jsons.integer(task.get("companyId")))?List.of("classify"):List.of());return Api.ok(data);}
 @PostMapping("/tasks/{id}/classification") Object classify(HttpServletRequest q,@PathVariable long id,@RequestBody Map<String,Object> body){var a=p.actor(q);return writes.run(q,body,()->{var task=records.lock(id);if(!"TASK".equals(task.get("kind")))throw ApiException.denied();int company=Jsons.integer(task.get("companyId"));p.leader(a,company);var old=classificationData(id);if(TaskService.integer(body,"expectedVersion")!=Jsons.integer(old.get("version")))throw ApiException.conflict();String complexity=TaskService.text(body,"complexity",16);if(!Set.of("SIMPLE","NORMAL","COMPLEX").contains(complexity))throw TaskService.invalid("复杂度无效");long record=insert("INSERT INTO task_classification_version(task_id,company_id,version,complexity,category,reason,created_by) VALUES(?,?,?,?,?,?,?)",id,company,Jsons.integer(old.get("version"))+1,complexity,TaskService.text(body,"category",50),TaskService.text(body,"reason",1000),a.uid());writes.audit(a,"TASK_CLASSIFICATION_APPEND",record);var data=classificationData(id);data.put("allowedActions",List.of("classify"));return data;});}
 @PostMapping("/kpi/calendar-simulations") Object simulate(HttpServletRequest q,@RequestBody Map<String,Object> body){var a=p.actor(q);int company=TaskService.integer(body,"companyId");access(a,company,true);if(!Boolean.TRUE.equals(body.get("simulation")))throw TaskService.invalid("仅支持simulation=true");return writes.run(q,body,()->{YearMonth period;try{period=YearMonth.parse(TaskService.text(body,"period",7));}catch(RuntimeException e){throw TaskService.invalid("期间应为YYYY-MM");}if(!period.isBefore(YearMonth.now(CalendarPolicy.ZONE)))throw TaskService.invalid("仅模拟已结束月份");Integer dept=body.get("deptId")==null?null:TaskService.integer(body,"deptId");if(a.departmentHead()){if(dept!=null&&!Objects.equals(dept,a.dept()))throw ApiException.denied();dept=a.dept();}if(dept!=null){var d=records.get(dept);if(!"DEPARTMENT".equals(d.get("kind"))||Jsons.integer(d.get("companyId"))!=company)throw ApiException.denied();}
  long calendarId=TaskService.number(body,"calendarVersionId"),templateId=TaskService.number(body,"templateId");Map<String,Object> calendarSnapshot=calendarId==0?Map.of():configuration("company_calendar_version",calendarId,company);var calendar=calendarId==0?CalendarPolicy.baseline():CalendarPolicy.validate(calendarSnapshot);Map<String,Object> templateSnapshot=templateId==0?map("weights",Kpi.WEIGHTS,"complexityWeights",map("SIMPLE",1,"NORMAL",1,"COMPLEX",1)):configuration("kpi_simulation_template",templateId,company);var weights=CalendarPolicy.weights(templateSnapshot.get("weights"));var factors=CalendarPolicy.complexity(templateSnapshot.get("complexityWeights"));
  Instant start=period.atDay(1).atStartOfDay(CalendarPolicy.ZONE).toInstant(),end=period.plusMonths(1).atDay(1).atStartOfDay(CalendarPolicy.ZONE).toInstant();var subs=new ArrayList<Map<String,Object>>();Map<Long,String> complexities=new TreeMap<>();Map<String,Object> classificationSnapshot=new TreeMap<>();for(var sub:records.list("SUB_TASK",company,dept)){Instant deadline=Records.instant(sub.get("deadline"));if(deadline.isBefore(start)||!deadline.isBefore(end))continue;var task=records.get(Jsons.number(sub.get("taskId")));if(Set.of("DRAFT","CANCELLED").contains(task.get("status")))continue;var copy=new TreeMap<String,Object>();for(String key:List.of("id","taskId","deptId","ownerId","status","deadline","originalDeadline","everOverdue","rejectCount","firstReceivedAt","submittedAt","dispatchedAt","createdAt")){Object value=sub.get(key);if(value!=null&&(key.endsWith("At")||key.endsWith("Deadline")||key.equals("deadline")))value=Records.instant(value).toString();copy.put(key,value);}subs.add(copy);long taskId=Jsons.number(sub.get("taskId"));var classification=classificationData(taskId);complexities.put(taskId,String.valueOf(classification.get("complexity")));classificationSnapshot.put(String.valueOf(taskId),classification);if(subs.size()>2000)throw new ApiException(413,"SIMULATION_TOO_LARGE","模拟最多2000条子任务，请缩小部门范围");}
  List<Map<String,Object>> rows=new ArrayList<>();for(var department:records.list("DEPARTMENT",company,null)){int departmentId=Jsons.integer(department.get("id"));if(dept!=null&&dept!=departmentId)continue;var departmentSubs=subs.stream().filter(s->Jsons.integer(s.get("deptId"))==departmentId).toList();var baseline=CalendarPolicy.score(departmentSubs,CalendarPolicy.baseline(),Kpi.WEIGHTS,Map.of("NORMAL",BigDecimal.ONE),Map.of());var candidate=CalendarPolicy.score(departmentSubs,calendar,weights,factors,complexities);BigDecimal old=(BigDecimal)baseline.get("total"),proposed=(BigDecimal)candidate.get("total");rows.add(map("deptId",departmentId,"deptName",department.get("name"),"sampleCount",departmentSubs.size(),"baseline",baseline,"candidate",candidate,"delta",old==null||proposed==null?null:proposed.subtract(old)));}
  String snapshot=json.write(map("companyId",company,"deptId",dept,"period",period.toString(),"calendarVersionId",calendarId,"calendar",calendarSnapshot,"templateId",templateId,"template",templateSnapshot,"classifications",classificationSnapshot,"subTasks",subs,"timezone","Asia/Shanghai","policyVersion",1));String hash=Writes.sha(snapshot);var result=map("companyId",company,"deptId",dept,"period",period.toString(),"simulation",true,"inputHash",hash,"rows",rows,"correlation",CalendarPolicy.correlation(rows));String reason=TaskService.text(body,"reason",1000);long id=insert("INSERT INTO calendar_simulation(company_id,dept_id,period,reason,input_hash,input_snapshot,result_json,created_by) VALUES(?,?,?,?,?,?,?,?)",company,dept,period.toString(),reason,hash,snapshot,json.write(result),a.uid());writes.audit(a,"KPI_CALENDAR_SIMULATE",id);result.put("id",id);result.put("reason",reason);return result;});}
 Map<String,Object> configuration(String table,long id,int company){if(!VERSION_TABLES.contains(table))throw new IllegalArgumentException();var rows=db.queryForList("SELECT payload FROM "+table+" WHERE id=? AND company_id=?",id,company);if(rows.isEmpty())throw ApiException.denied();return json.map(String.valueOf(rows.getFirst().get("payload")));}
 @GetMapping("/kpi/calendar-simulations/{id}") Object simulation(HttpServletRequest q,@PathVariable long id){var a=p.actor(q);var rows=db.queryForList("SELECT * FROM calendar_simulation WHERE id=?",id);if(rows.isEmpty())throw new ApiException(404,"NOT_FOUND","模拟不存在");var row=rows.getFirst();access(a,Jsons.integer(row.get("company_id")),true);if(a.departmentHead()&&(row.get("dept_id")==null||!Objects.equals(a.dept(),Jsons.integer(row.get("dept_id")))))throw ApiException.denied();if(!Writes.sha(String.valueOf(row.get("input_snapshot"))).equals(row.get("input_hash")))throw new ApiException(503,"SNAPSHOT_INTEGRITY_FAILURE","模拟快照校验失败");var result=json.map(String.valueOf(row.get("result_json")));result.put("id",id);result.put("reason",row.get("reason"));result.put("createdAt",Records.instant(row.get("created_at")).toString());return Api.ok(result);}
}
